const navItem=document.querySelectorAll(".top-nav");document.querySelectorAll(".dropdown-btn").forEach(e=>{const a=e.parentElement.nextElementSibling;e.addEventListener("click",e=>{a?.classList.toggle("show")})}),navItem.forEach(e=>{const a=e.querySelector(".dropdown-menu"),l=e.querySelector(".nav-link");window.matchMedia("(min-width: 992px)").matches&&(e.addEventListener("mouseenter",()=>{a?.classList.add("show"),l?.classList.add("hover")}),e.addEventListener("mouseleave",()=>{a?.classList.remove("show"),l?.classList.remove("hover")}))});const logo=document.querySelector("#logo"),navbar=document.querySelector(".navbar");let scrollFrame=null,navIsScaled=!1;const updateNavigationScale=()=>{scrollFrame=null;const e=window.scrollY>30;e!==navIsScaled&&logo&&navbar&&(navIsScaled=e,logo.classList.toggle("scale-img",e),navbar.classList.toggle("scale-nav",e))};window.addEventListener("scroll",()=>{null===scrollFrame&&(scrollFrame=window.requestAnimationFrame(updateNavigationScale))},{passive:!0});